import { SvgIcon } from '@mui/material';

export const LhBrandLogo = ({
  width = 180,
  height = 72,
}: {
  width?: number;
  height?: number;
} = {}) => {
  return (
    <SvgIcon
      sx={{
        width: `${width}px`,
        height: `${height}px`,
      }}
    >
      <svg
        width={108}
        height={72}
        viewBox='0 0 108 72'
        fill='none'
        xmlns='http://www.w3.org/2000/svg'
        xmlnsXlink='http://www.w3.org/1999/xlink'
      >
        <rect width='108' height='72' fill='url(#pattern0_4697_264499)' />
        <defs>
          <pattern
            id='pattern0_4697_264499'
            patternContentUnits='objectBoundingBox'
            width='1'
            height='1'
          >
            <use
              xlinkHref='#image0_4697_264499'
              transform='scale(0.00277778 0.00416667)'
            />
          </pattern>
          <image
            id='image0_4697_264499'
            width='360'
            height='240'
            preserveAspectRatio='none'
            xlinkHref='data:image/png;base64,'
          />
        </defs>
      </svg>
    </SvgIcon>
  );
};
